-- stochastic-processes implementation for MonteCarloSampler
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.

local Module = {}
function Module.Uniform(stream,count,minimum,maximum)
    assert(count>=1 and count%1==0 and maximum>=minimum,"invalid uniform sample request")
    local samples=table.create(count); for i=1,count do samples[i]=minimum+(maximum-minimum)*stream:Next() end; return samples
end
function Module.Estimate(samples,integrand)
    assert(#samples>0,"sample set cannot be empty"); local total=0; local squares=0
    for _,x in ipairs(samples) do local value=integrand(x); total+=value; squares+=value*value end
    local mean=total/#samples; return mean,math.sqrt(math.max(0,squares/#samples-mean*mean)/#samples)
end

return Module
